 * The same tests show that is a LOCK ONLY IF THE BODY NEVER GOES BACK. Walking
 * back along the route to the frontier it actually reached and re-traversing
 * from there credits the full eighteen units exactly — ordinary movement, no
 * reset, no second F, no new marker, and the units earned before the deviation
 * are retained throughout.
 *
 * The cheaper reconciliation — letting the frontier creep toward the body's own
 * projection at walking pace — was implemented, measured and REMOVED: it pays
 * for the omitted wedge with displacement spent anywhere in the corridor,
 * including a wiggle at the far end, which the chapter's signed reading of
 * `#/story/events/21` and `#/guidance/objectives/13` forbids.
 *
 * WHAT THIS RULE IS NOT. It is not a claim that every projection ahead of one
 * frame's displacement is a cut corner. A body that walks THROUGH a vertex and
 * overshoots it — the ordinary way a human rounds a corner — turns onto the next
 * leg already a little way along it, and this function's ceiling then rejects
 * that whole projection frame after frame, because from there the projection and
 * the ceiling advance at the same rate. Measured live: credit 6, projection
 * 6.2944830004, ceiling 6.1635971455, frozen
 * (`producer-common-entry-crossing-review.json`, call 298). That case is settled
 * by `nextRouteCoverage` below, from actual ordered coverage between two real
 * feet, and NOT by loosening anything here: this function is unchanged, and the
 * early cut it refuses stays refused there too.
 */
export function routeProgressUnits(
  route: readonly CommonGroundPoint[],
  body: CommonGroundPoint,
  previousUnits: number,
  displacementUnits: number,
  corridorRadius = 2.5
): number {
  // NO DISPLACEMENT, NO PROGRESS. A stationary body earns nothing, however long
  // it stands there and however many times it is sampled, which is what makes
  // standing at C worth zero and a timer worth nothing at all.
  if (!(displacementUnits > 0)) return previousUnits;
  // The ceiling is computed ONCE from the progress already earned, so repeated
  // iterations of the scan below cannot compound an allowance, and a later
  // segment's proximity cannot be claimed ahead of the frontier.
  const ceiling = previousUnits + displacementUnits;
  let travelled = 0;
  let best = previousUnits;
  for (let index = 1; index < route.length; index += 1) {
    const from = route[index - 1];
    const to = route[index];
    const segment = distanceBetween(from, to);
    if (segment <= 0) continue;
    const dx = to.x - from.x;
    const dy = to.y - from.y;
    const dz = to.z - from.z;
    const t = Math.max(0, Math.min(1,
      ((body.x - from.x) * dx + (body.y - from.y) * dy + (body.z - from.z) * dz)
        / (segment * segment)));
    const closest = { x: from.x + dx * t, y: from.y + dy * t, z: from.z + dz * t };
    const arc = travelled + segment * t;
    if (arc > best && arc <= ceiling && distanceBetween(body, closest) <= corridorRadius) {
      best = arc;
    }
    travelled += segment;
  }
  return Math.min(best, travelled);
}

